/* CSS Reset */
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    /*
      ROOT VARIABLES - CUSTOMIZE YOUR COLORS HERE

      Replace [primary-color] and [secondary-color] with your brand colors
      Example: #1e5f8f for blue, #d4af37 for gold

      Ensure sufficient contrast for accessibility (WCAG AA):
      - Primary color should contrast with white text (4.5:1 minimum)
      - Secondary color should contrast with dark text (4.5:1 minimum)
      - Test at https://webaim.org/resources/contrastchecker/
    */
    :root {
      --primary-blue: [primary-color];
      --secondary-gold: [secondary-color];
      --text-dark: #2c3e50;
      --text-light: #ffffff;
      --bg-light: #f8f9fa;
      --bg-white: #ffffff;
      --border-color: #dee2e6;
      --shadow: 0 2px 8px rgba(0,0,0,0.1);
      --transition: all 0.3s ease;
    }

    /* Typography */
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      line-height: 1.6;
      color: var(--text-dark);
      background-color: var(--bg-light);
    }

    h1, h2, h3 {
      font-weight: 700;
      line-height: 1.2;
      margin-bottom: 1rem;
    }

    h1 { font-size: 2.5rem; }
    h2 { font-size: 2rem; }
    h3 { font-size: 1.5rem; }

    /* Header */
    header {
      background-color: var(--primary-blue);
      color: var(--text-light);
      padding: 1rem 0;
      position: sticky;
      top: 0;
      z-index: 1000;
      box-shadow: var(--shadow);
    }

    .header-container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 1rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .logo {
      font-size: 1.5rem;
      font-weight: 700;
    }

    /*
      LANGUAGE TOGGLE BUTTON

      This button switches between languages. It shows the name of the
      language you can switch TO (not the current language).

      Customize:
      - Change border color to match your brand
      - Adjust padding for different button sizes
      - Modify hover effect for your design
    */
    .language-toggle {
      padding: 0.5rem 1rem;
      border: 2px solid var(--text-light);
      border-radius: 4px;
      background: transparent;
      color: var(--text-light);
      cursor: pointer;
      font-weight: 600;
      transition: var(--transition);
    }

    .language-toggle:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    .language-toggle:focus {
      outline: 2px solid var(--secondary-gold);
      outline-offset: 2px;
    }

    /* Hide inactive language label in toggle button */
    [data-lang="[language1]"] .lang-[language1],
    [data-lang="[language2]"] .lang-[language2] {
      display: none;
    }

    /*
      SINGLE-LANGUAGE TOGGLE LAYOUT

      This is the key CSS for single-language display:
      - Only ONE language is visible at a time (not side-by-side)
      - Switching languages completely replaces content
      - Fade transitions provide smooth visual feedback

      Do NOT modify unless you understand the toggle mechanism
    */
    .bilingual-container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 2rem 1rem;
    }

    /* Single-language toggle: only one visible at a time */
    .content-[language1],
    .content-[language2] {
      transition: opacity 0.3s ease;
    }

    /* Hide inactive language completely */
    .bilingual-container[data-lang="[language1]"] .content-[language2] {
      display: none;
    }

    .bilingual-container[data-lang="[language2]"] .content-[language1] {
      display: none;
    }

    /* Fade transitions */
    .fade-in {
      animation: fadeIn 0.3s ease-in;
    }

    .fade-out {
      animation: fadeOut 0.3s ease-out;
    }

    @keyframes fadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }

    @keyframes fadeOut {
      from { opacity: 1; }
      to { opacity: 0; }
    }

    /*
      SECTIONS

      Each section is a white card with shadow and rounded corners.
      Customize spacing and styling to match your brand.
    */
    section {
      background: var(--bg-white);
      padding: 2rem;
      margin-bottom: 2rem;
      border-radius: 8px;
      box-shadow: var(--shadow);
    }

    /*
      HERO SECTION

      The top banner with your business name and main call-to-action.
      Uses gradient background with your primary color.
    */
    .hero {
      background: linear-gradient(135deg, var(--primary-blue) 0%, #2c7fb8 100%);
      color: var(--text-light);
      text-align: center;
      padding: 3rem 2rem;
    }

    .hero h1 {
      margin-bottom: 0.5rem;
    }

    .hero-tagline {
      font-size: 1.25rem;
      margin-bottom: 2rem;
      opacity: 0.9;
    }

    /*
      IMAGES

      Replace image URLs with your own. Ensure:
      - All images have descriptive alt text for accessibility
      - Images are optimized for web (under 500KB each)
      - Images are at least 1200px wide for desktop displays
    */
    .hero img {
      max-width: 100%;
      height: auto;
      border-radius: 8px;
      margin: 2rem 0;
      box-shadow: var(--shadow);
    }

    section img {
      max-width: 100%;
      height: auto;
      border-radius: 8px;
      margin: 1rem 0;
      box-shadow: var(--shadow);
    }

    /*
      CALL-TO-ACTION BUTTONS

      Primary button: Uses secondary color (accent)
      Secondary button: Transparent with border
    */
    .cta-buttons {
      display: flex;
      gap: 1rem;
      justify-content: center;
      flex-wrap: wrap;
    }

    .btn {
      display: inline-block;
      padding: 0.75rem 1.5rem;
      border-radius: 4px;
      text-decoration: none;
      font-weight: 600;
      transition: var(--transition);
    }

    .btn-primary {
      background: var(--secondary-gold);
      color: var(--text-dark);
    }

    .btn-primary:hover {
      background: #c49c2e;
      transform: translateY(-2px);
    }

    .btn-secondary {
      background: transparent;
      color: var(--text-light);
      border: 2px solid var(--text-light);
    }

    .btn-secondary:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    /*
      STATS SECTION

      Display key business statistics (years, achievements, etc.)
      Grid layout adapts to screen size automatically
    */
    .stats {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 1.5rem;
      margin-top: 2rem;
    }

    .stat {
      text-align: center;
    }

    .stat-number {
      font-size: 2rem;
      font-weight: 700;
      color: var(--primary-blue);
    }

    .stat-label {
      font-size: 0.9rem;
      color: #6c757d;
    }

    /*
      MENU/CATALOG SECTIONS

      These sections display your products, services, or menu items.
      Customize icons, layout, and styling to match your content.

      .menu-section: Container for each category (appetizers, mains, etc.)
      .menu-item: Individual item (product, dish, service)
      .menu-item.specialty: Featured/highlighted item
    */
    .menu-section {
      margin-bottom: 2rem;
    }

    .menu-header {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-bottom: 1.5rem;
      padding-bottom: 0.75rem;
      border-bottom: 2px solid var(--border-color);
    }

    .menu-icon {
      font-size: 2rem;
    }

    .menu-items {
      display: grid;
      gap: 1.5rem;
    }

    .menu-item {
      padding: 1rem;
      border-left: 3px solid var(--primary-blue);
      background: var(--bg-light);
      border-radius: 0 4px 4px 0;
    }

    .menu-item.specialty {
      border-left-color: var(--secondary-gold);
      background: #fffbf0;
    }

    .menu-item-header {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      margin-bottom: 0.5rem;
    }

    .menu-item-name {
      font-weight: 600;
      font-size: 1.1rem;
      color: var(--text-dark);
    }

    .menu-item-price {
      font-weight: 700;
      color: var(--primary-blue);
      font-size: 1.1rem;
    }

    .menu-item-description {
      font-size: 0.95rem;
      color: #6c757d;
      line-height: 1.5;
    }

    .specialty-badge {
      display: inline-block;
      padding: 0.25rem 0.5rem;
      background: var(--secondary-gold);
      color: var(--text-dark);
      border-radius: 3px;
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      margin-left: 0.5rem;
    }

    /*
      CONTACT SECTION

      Display address, phone, email, hours, etc.
      Uses icons (emoji or image) for visual clarity
    */
    .contact-info {
      display: grid;
      gap: 1rem;
    }

    .contact-item {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
    }

    .contact-icon {
      font-size: 1.5rem;
      color: var(--primary-blue);
    }

    .contact-details {
      flex: 1;
    }

    .contact-label {
      font-weight: 600;
      margin-bottom: 0.25rem;
    }

    /* Footer */
    footer {
      background-color: var(--text-dark);
      color: var(--text-light);
      padding: 2rem 1rem;
      text-align: center;
    }

    .footer-content {
      max-width: 1200px;
      margin: 0 auto;
    }

    .footer-note {
      font-size: 0.9rem;
      opacity: 0.8;
      margin-top: 1rem;
      padding-top: 1rem;
      border-top: 1px solid rgba(255, 255, 255, 0.1);
    }

    /*
      ACCESSIBILITY

      Skip link allows keyboard users to jump to main content.
      REQUIRED for WCAG 2.1 AA compliance - do not remove.
    */
    .skip-link {
      position: absolute;
      top: -40px;
      left: 0;
      background: var(--primary-blue);
      color: var(--text-light);
      padding: 0.5rem 1rem;
      text-decoration: none;
      z-index: 100;
    }

    .skip-link:focus {
      top: 0;
    }

    /* Print Styles */
    @media print {
      header {
        position: static;
        box-shadow: none;
      }

      .language-toggle,
      .skip-link {
        display: none;
      }

      section {
        box-shadow: none;
        page-break-inside: avoid;
      }

      .hero {
        background: none;
        color: var(--text-dark);
      }

      .btn {
        display: none;
      }
    }

    /*
      MOBILE RESPONSIVE

      Adjusts layout for screens smaller than 768px.
      Reduces font sizes, padding, and switches to vertical layouts.
    */
    @media (max-width: 767px) {
      h1 { font-size: 2rem; }
      h2 { font-size: 1.5rem; }
      h3 { font-size: 1.25rem; }

      .hero {
        padding: 2rem 1rem;
      }

      section {
        padding: 1.5rem 1rem;
      }

      .menu-item-header {
        flex-direction: column;
        align-items: flex-start;
      }
    }

    /* Utilities */
    .text-center { text-align: center; }
    .mb-1 { margin-bottom: 1rem; }
    .mb-2 { margin-bottom: 2rem; }

// Language toggle functionality (path-based routing)
    // Note: Language is determined by directory (/[language1]/ or /[language2]/)
    // The data-lang attribute is set on <html> element for each language version
    (function() {
      const toggle = document.querySelector('.language-toggle');

      // Language toggle navigates to the other language version
      if (toggle) {
        toggle.addEventListener('click', () => {
          const currentLang = document.documentElement.getAttribute('data-lang');
          const targetLang = currentLang === '[language1]' ? '[language2]' : '[language1]';
          const currentPath = window.location.pathname;

          // Replace /[language1]/ with /[language2]/ or vice versa in the URL
          const newPath = currentPath.replace(/\/([a-z]{2})\//, `/${targetLang}/`);
          window.location.href = newPath;
        });
      }
    })();

    //
    // WEBMCP TOOL DEFINITIONS
    //
    // These tools allow AI agents to interact with your website programmatically.
    // Customize the tools to expose your business data and functionality.
    //
    // Example tools:
    // - toggle-language: Switch between languages
    // - menu-query: Query menu/catalog items
    // - reservation-info: Get contact and booking information
    // - location-info: Get geographic location data
    //
    window.mcpTools = {
      'toggle-language': {
        name: 'toggle-language',
        description: 'Switch between [Language1] and [Language2] language versions',
        inputSchema: {
          type: 'object',
          properties: {
            lang: {
              type: 'string',
              enum: ['[language1]', '[language2]'],
              description: 'Target language code'
            }
          },
          required: ['lang']
        },
        execute: async (params) => {
          const { lang } = params;
          const currentPath = window.location.pathname;

          // Navigate to the target language version (path-based)
          const newPath = currentPath.replace(/\/([a-z]{2})\//, `/${lang}/`);
          window.location.href = newPath;

          return { success: true, targetLang: lang, targetUrl: newPath };
        }
      },
      'menu-query': {
        name: 'menu-query',
        description: 'Query menu/catalog items by category or search term',
        inputSchema: {
          type: 'object',
          properties: {
            category: {
              type: 'string',
              description: 'Category to query (customize with your categories)'
            },
            search: {
              type: 'string',
              description: 'Search term for items'
            }
          }
        },
        execute: async (params) => {
          // Extract menu/catalog data from DOM
          const menuItems = Array.from(document.querySelectorAll('.menu-item')).map(item => ({
            name: item.querySelector('.menu-item-name').textContent,
            price: item.querySelector('.menu-item-price')?.textContent || 'N/A',
            description: item.querySelector('.menu-item-description').textContent,
            specialty: item.classList.contains('specialty')
          }));
          return { success: true, items: menuItems };
        }
      },
      'reservation-info': {
        name: 'reservation-info',
        description: 'Get business contact and reservation information',
        inputSchema: {
          type: 'object',
          properties: {}
        },
        execute: async () => {
          return {
            success: true,
            info: {
              phone: '[phone-number]',
              email: '[email-address]',
              hours: '[opening-hours-display]',
              address: '[street-address], [location], [region], [country-name]',
              coordinates: { lat: [Latitude], lng: [Longitude] }
            }
          };
        }
      },
      'location-info': {
        name: 'location-info',
        description: 'Get geographic location and directions information',
        inputSchema: {
          type: 'object',
          properties: {}
        },
        execute: async () => {
          return {
            success: true,
            location: {
              address: '[street-address], [location], [region], [country-name]',
              coordinates: { lat: [Latitude], lng: [Longitude] },
              region: '[region]',
              country: '[country-name]'
            }
          };
        }
      }
    };

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });
    });
